<script setup lang="ts">
import {useRouter} from 'vue-router'
import SampleResearchReview from './SampleResearchReview.vue'
import {dateText,label} from '../experiments/model'
import {qualities} from '../measurements/model'
defineProps<{runs:any[];writable:boolean}>()
const router=useRouter()
function go(s:any,p:any){void router.push({path:'/sample-history',query:{sample_id:s.sample_id,process_id:p.process_id}})}
function measurementMean(s:any,r:any,stage:string){return r[stage+'_mean_nm']??s.research_review?.measurements?.find((m:any)=>m.measurement_id===r[stage+'_measurement_id'])?.thickness_mean_nm??null}
const number=(v:any)=>v==null?'未记录':Number(v).toLocaleString('zh-CN',{maximumSignificantDigits:9})
</script>
<template><section data-testid="experiment-results" class="experiment-results"><h3>实验结果与参与样品</h3><p v-if="!runs.length" class="readonly-note">尚无实际执行，计划条件不作为处理事实。</p>
<article v-for="run in runs" :key="run.process_id" class="run-results">
<header class="run-heading"><div><p class="run-code">{{run.process_code}} · {{run.started_at?dateText(run.started_at):'实际时间未记录'}}</p><h3>{{run.plan?.title||'独立实验'}} · {{label(run.process_mode)}}</h3><p v-if="run.voided_at" class="danger-text">已作废，不计入累计</p></div><div class="run-actions"><router-link :to="{path:'/processes',query:{process_id:run.process_id}}">打开此次执行及条件</router-link><router-link v-if="writable&&!run.voided_at" class="el-button is-link" :to="{path:'/imports',query:{process_id:run.process_id}}">导入本次实验数据</router-link></div></header>
<p class="run-conditions">实际记录：R1 {{run.r1_temp_c??'未记录'}} °C / R2 {{run.r2_temp_c??'未记录'}} °C · N₂ {{run.n2_flow_sccm??'未记录'}} sccm</p><p v-if="run.notes" class="field-hint">执行备注：{{run.notes}}</p>
<p v-if="!run.samples?.length" class="readonly-note">尚未绑定样品。</p>
<el-table v-else :data="run.samples" class="sample-result-table" aria-label="参与样品科研结果">
<el-table-column label="样品 / 材料" min-width="160"><template #default="{row}"><strong>{{row.sample.sample_code}}</strong><p>{{row.batch?.batch_code||'批次未记录'}} · {{row.batch?.material||'材料未记录'}}</p><el-button link type="primary" @click="go(row,run)">完整科研履历 / 装卸记录</el-button></template></el-table-column>
<el-table-column label="本片循环 / 处理节点" min-width="190"><template #default="{row}"><strong>{{row.cycles_confirmed?row.full_ale_cycles+' cycles':'循环未确认'}}</strong><p>{{row.execution_evidence==='not_confirmed'?'仅绑定，未确认处理':row.execution_evidence==='voided'?'执行已作废':row.participation_status==='unloaded'?'已记录取出':'已记录装载及执行时间'}}</p><p>装载 {{row.load_event?.step_index==null?'节点未记录':'#'+row.load_event.step_index}} → 取出 {{row.unload_event?.step_index==null?'节点未记录':'#'+row.unload_event.step_index}}</p><p>体系 {{row.chemistry_name||'未确认'}}</p></template></el-table-column>
<el-table-column label="前 → 后均值 / nm" min-width="180"><template #default="{row}"><template v-if="row.research_review?.results?.length"><p v-for="r in row.research_review.results" :key="r.after_measurement_id"><strong>{{number(measurementMean(row,r,'before'))}} → {{number(measurementMean(row,r,'after'))}}</strong></p></template><template v-else><p v-for="m in row.research_review?.measurements??[]" :key="m.measurement_id">{{m.measurement_code}} · {{number(m.thickness_mean_nm)}} nm</p><p v-if="!row.research_review?.measurements?.length">尚未测量</p><p v-else>前后配对未确认</p></template></template></el-table-column>
<el-table-column label="表观减薄量 / nm" min-width="210"><template #default="{row}"><div v-for="r in row.research_review?.results??[]" :key="r.after_measurement_id"><p v-if="r.reason" class="result-warning">无法计算：{{r.reason}}</p><template v-else><strong class="result-value">{{number(r.thinning_nm)}}</strong><p v-if="r.epc_nm_per_cycle!=null">{{number(r.epc_nm_per_cycle)}} nm/cycle · {{r.effective_cycles}} cycles</p><p v-else>{{r.epc_reason||'每循环依据未确认'}}</p></template></div><p v-if="!row.research_review?.results?.length">暂无已确认配对</p></template></el-table-column>
<el-table-column label="质量 / 来源" min-width="160"><template #default="{row}"><div v-for="m in row.research_review?.measurements??[]" :key="m.measurement_id"><p>{{qualities[m.quality_flag]||m.quality_flag||'质量未知'}} · 可用 {{m.valid_point_count??'未知'}} / {{m.point_count??'未知'}} 点</p><router-link v-if="m.source_file_id" :to="{path:'/source-files',query:{id:m.source_file_id}}">原件</router-link></div><span v-if="!row.research_review?.measurements?.length">尚无测量来源</span></template></el-table-column>
</el-table>
<p class="field-hint result-definition">表观减薄量 = 前均值 − 后均值；正值减薄，负值增厚。每循环值仅展示服务器已核验结果，不使用设备总循环推算。</p>
<details v-for="s in run.samples" :key="s.process_sample_id" class="sample-result" data-testid="experiment-sample-result"><summary>{{s.sample.sample_code}} · 测量详情与计算依据</summary><p>本次逐片循环：{{s.cycles_confirmed?s.full_ale_cycles:'未确认'}}<span v-if="s.unload_event?.step_index!=null"> · 取出步骤 {{s.unload_event.step_index}}</span></p><SampleResearchReview :sample="s.sample" :review="s.research_review" :writable="false"/><router-link v-if="writable&&!run.voided_at" :to="{path:'/imports',query:{process_id:run.process_id,sample_id:s.sample_id}}">导入该样品本次测量</router-link></details>
</article></section></template>
<style scoped>.run-results{margin:16px 0 24px;padding:20px;border:1px solid var(--line);border-radius:13px;background:#f8fafc;box-shadow:4px 4px 14px #c7d3dc40,-3px -3px 12px #fff}.run-heading{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.run-heading h3{font-size:19px;line-height:1.6;margin:0 0 10px}.run-code{font-size:11px;letter-spacing:.4px;color:var(--muted);margin:0 0 8px}.run-actions{display:flex;flex-wrap:wrap;align-items:center;gap:10px;font-size:12px}.run-actions a{color:#086d79;min-height:36px;padding:6px 0}.run-conditions{font-size:12px;color:var(--muted);margin:0 0 18px}.sample-result-table{--el-table-tr-bg-color:transparent;--el-table-header-bg-color:#edf3f6;--el-table-bg-color:transparent}.sample-result-table p{font-size:12px;color:var(--muted);line-height:1.8;margin:5px 0}.sample-result-table .result-warning{color:#8a5510}.sample-result-table .el-button{font-size:12px;white-space:normal;height:auto;line-height:1.7;text-align:left}.sample-result-table a{color:#086d79}.result-value{font-size:23px;color:#076d78;font-variant-numeric:tabular-nums}.sample-result{border-top:1px solid var(--line);padding:9px 0}.sample-result summary{min-height:40px;padding:8px 0;cursor:pointer;color:#086d79;font-size:13px;font-weight:600}.result-definition{margin:14px 0 18px}@media(max-width:640px){.run-results{padding:14px}.run-heading{flex-wrap:wrap}.run-heading h3{font-size:17px}.run-code{overflow-wrap:anywhere}.sample-result-table{max-width:100%}}
</style>
